 "content": "def transform(grid):
    """Copy the rare non-background motif onto every matching blank placement."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    # The marked motif is the rarest non-background color; frequent noise stays fixed.
    motif_color = min(counts, key=counts.get)
    motif = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == motif_color]
    min_r = min(r for r, _ in motif)
    min_c = min(c for _, c in motif)
    shape = [(r - min_r, c - min_c) for r, c in motif]
    out = [row[:] for row in grid]
    max_r = max(r for r, _ in shape)
    max_c = max(c for _, c in shape)
    for r0 in range(h - max_r):
        for c0 in range(w - max_c):
            cells = [(r0 + dr, c0 + dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = motif_color
    return out
